 const equal=(a,b)=>{let aa=new TextEncoder().encode(a),bb=new TextEncoder().encode(b),d=aa.length^bb.length;for(let i=0;i<Math.max(aa.length,bb.length);i++)d|=(aa[i]||0)^(bb[i]||0);return d===0};
 const hash=p=>{const salt=randomBytes(16).toString("hex"),rounds=250000;return "pbkdf2_sha256$"+rounds+"$"+salt+"$"+pbkdf2Sync(p,Buffer.from(salt,"hex"),rounds,32,"sha256").toString("hex")};
 const check=(p,h)=>{try{const a=h.split("$"),n=Number(a[1]);return a[0]==="pbkdf2_sha256"&&n>=100000&&n<=1000000&&equal(pbkdf2Sync(p,Buffer.from(a[2],"hex"),n,32,"sha256").toString("hex"),a[3])}catch{return false}};
