 async function upstream(path,body){const r=await fetch(litellm+path,{method:"POST",headers:{"Authorization":"Bearer "+master,"Content-Type":"application/json"},body:JSON.stringify(body),signal:AbortSignal.timeout(20000)});let v={};try{v=await r.json()}catch{}if(!r.ok)throw Error("LiteLLM: "+String(v.error?.message||v.detail||r.status).slice(0,240));return v}
 const days=()=>{const f=new Intl.DateTimeFormat("en-US",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}),label=new Intl.DateTimeFormat("pt-BR",{timeZone:"America/Sao_Paulo",month:"2-digit",day:"2-digit"});const out=[];for(let i=6;i>=0;i--){const dt=new Date(Date.now()-i*86400000),p=Object.fromEntries(f.formatToParts(dt).map(x=>[x.type,x.value]));out.push({day:p.year+"-"+p.month+"-"+p.day,label:label.format(dt),requests:0,tokens:0})}return out};
